  "Greeting_HomeTownContent": {"ko":"대한민국 경기도","en":"Gyeonggi-do, Republic of Korea","ja":"大韓民国 京畿道","zh":"大韩民国 京畿道","vi":"Tỉnh Gyeonggi, Hàn Quốc","th":"จังหวัดคยองกี สาธารณรัฐเกาหลี","ru":"Провинция Кёнгидо, Республика Корея","id":"Gyeonggi-do, Republik Korea"},
