  "Photo_Game_popup_title_success": {"ko":"다 찾았어요!","en":"Found them all!","ja":"全部見つけました！","zh":"全部找到了！","vi":"Đã tìm thấy tất cả!","th":"หาเจอครบแล้วค่ะ!","ru":"Все найдены!","id":"Berhasil temukan semua!"},
